  'landing.partners.firewall.title': "What you cannot buy here",
  'landing.partners.footer.note': "Studentkare is still being built, and this page lists what is missing on purpose. We do not show partner logos until a partner has signed and agreed in writing to appear.",
  'landing.partners.footer.privacy': "Privacy",
  'landing.partners.footer.terms': "Terms",
  'landing.partners.gap.body': "Our designs say the rate is published on every line. No rate is configured in the system yet, so there is nothing honest to print here. It will appear on this page and on every statement line once it is set — and not before.",
  'landing.partners.gap.title': "Commission is not published yet.",
  'landing.partners.lede': "There are no sponsored slots, because there is nothing to sell you. Provider search sorts by whether you serve the student’s pincode, then alphabetically — never by what you pay. The way to be seen is to serve a campus well.",
  'landing.partners.nfs.ads': "Advertising slots. There are none, and paying for anything never grants sight of a member’s record.",
  'landing.partners.nfs.record': "Anything in a student’s health record — for targeting, segmentation or any other purpose. Clinical data does not reach commercial surfaces.",
  'landing.partners.nfs.search': "Position in search results. The ordering is pincode match, then name, and the API states that on every response.",
