  'landing.plans.empty': "No plans are published right now.",
  'landing.plans.faq.a1': "Everything you stored stays in your record, readable and exportable. Stopping a plan ends its optional benefits — nothing you already stored is deleted or locked.",
  'landing.plans.faq.a2': "No. Clinical triage is based on medical urgency alone. A plan pays for optional benefits, never a place in a clinical queue.",
  'landing.plans.faq.a3': "No. Studentkare plans are memberships with optional benefits. They are not health insurance and do not replace emergency medical cover.",
  'landing.plans.faq.a4': "Yes, if your campus takes an institutional plan. Even when the institution pays, your records stay private — the college cannot open them.",
