  'landing.programs.cta': "Book a consult to start →",
  'landing.programs.ctaNote': "A clinician enrols you after a consult. Enrolment is free; consults and tests inside a programme are priced per use. Leave whenever you like — your records stay yours.",
  'landing.programs.eyebrow': "CARE PROGRAMMES",
  'landing.programs.faq1A': "No, and it should not. A programme keeps things steady during term — refills, repeat panels, someone to call. Your treating doctor stays the treating doctor, and you can share what is recorded here with them.",
  'landing.programs.faq1Q': "I already have a doctor at home. Does this replace them?",
  'landing.programs.faq2A': "Enrolling is free. Consults, prescribed refills and lab tests inside a programme are priced per use, and each price is on screen before you confirm. There are no lock-in fees and no penalty for a missed appointment.",
  'landing.programs.faq2Q': "What does it cost?",
  'landing.programs.faq3A': "Yes. Teleconsults carry on over the holidays, and lab tests can be booked wherever a partner lab is listed near you.",
  'landing.programs.faq3Q': "Can I stay enrolled over the holidays?",
  'landing.programs.faq4A': "The standing consent ends the day you leave. Your records stay yours, in your vault, and you can export them.",
  'landing.programs.faq4Q': "What happens to my records if I leave?",
  'landing.programs.faq5A': "If you are 18 or older, no. Your records, diagnoses and prescriptions are not shown to your campus or your parents unless you choose to share them.",
  'landing.programs.faq5Q': "Will my parents be told?",
  'landing.programs.faqTitle': "Before you enrol.",
  'landing.programs.footerNote': "Care programmes do not replace your specialist at home. Your records are yours and you can export them.",
  'landing.programs.include1Body': "Not whoever is free. They see your history, so you stop re-explaining it.",
  'landing.programs.include1Title': "One clinician who keeps the thread",
  'landing.programs.include2Body': "Worked out from when it was issued and how long it runs — no reminder to set.",
  'landing.programs.include2Title': "Refills timed to your course",
  'landing.programs.include3Body': "A repeat panel appears in Preventive care when it is due.",
  'landing.programs.include3Title': "Tests scheduled, not remembered",
  'landing.programs.include4Body': "Kept for your clinician to see. Not scored, not reported to anyone.",
  'landing.programs.include4Title': "A dose schedule that records misses",
  'landing.programs.include5Body': "Crisis and campus health desk, one tap from anywhere in the app.",
  'landing.programs.include5Title': "Somewhere to go at 2 AM",
  'landing.programs.includesHeading': "What every programme includes",
  'landing.programs.includesTitle': "WHAT A PROGRAMME INCLUDES",
  'landing.programs.intro': "A hostel is a hard place to keep a condition steady — no fridge for insulin, no one noticing a missed dose, a specialist four hours away. A programme keeps the same clinician, the refills and the follow-up in one thread.",
  'landing.programs.introEyebrow': "ONGOING CARE",
  'landing.programs.listNote': "There is no self sign-up yet: a clinician enrols you after a consult.",
  'landing.programs.listTitle': "Four programmes",
  'landing.programs.nativeLede': "Ongoing care for long-term conditions and mental health while you study. Keep seeing someone who knows your history.",
  'landing.programs.nativeTitle': "Long-term health without having to go home.",
  'landing.programs.notBody': "Enrolling gives a named clinician a standing consent you can revoke. It does not hand anyone a live feed of your day.",
  'landing.programs.notEyebrow': "WHAT A PROGRAMME IS NOT",
  'landing.programs.notTitle': "Structure, not surveillance.",
