  'landing.clinician.title': "వచ్చిన వరుసలో కాదు, తీవ్రతను బట్టి వరుస.",
  'landing.consult.app.body': "Studentkare ఇంకా యాప్ స్టోర్లలో లేదు. ఈరోజే వాడటానికి వెబ్‌లో సైన్ ఇన్ చేయండి.",
  'landing.consult.app.cta': "సైన్ ఇన్ →",
  'landing.consult.app.eyebrow': "మొదలుపెట్టండి",
  'landing.consult.app.label': "Studentkare వాడండి",
  'landing.consult.app.title': "మీ రికార్డులు, మీ క్యాంప్ స్లాట్లు, మీ కార్డ్ — అన్నీ ఒకే చోట.",
  'landing.consult.banner.label': "డాక్టర్‌ను సంప్రదించండి",
  'landing.consult.banner.title': "డాక్టర్‌తో మాట్లాడండి. ప్రిస్క్రిప్షన్ మీ వాల్ట్‌లోకి వస్తుంది.",
  'landing.consult.chip.mode': "వీడియో లేదా చాట్",
  'landing.consult.chip.price': "బుక్ చేసే ముందే ఫీజు కనిపిస్తుంది",
  'landing.consult.eyebrow': "డాక్టర్‌ను సంప్రదించండి",
  'landing.consult.faq.again.a': "మీ పాత డాక్టర్‌కు ఖాళీ స్లాట్లు ఉంటే, మళ్లీ వారినే బుక్ చేయొచ్చు. లేకపోతే వేరే డాక్టర్‌ను బుక్ చేయొచ్చు. అత్యవసరమైతే స్లాట్ కోసం ఆగకండి — SOS బటన్ నొక్కండి లేదా 112కి కాల్ చేయండి.",
  'landing.consult.faq.again.q': "అదే డాక్టర్‌ను మళ్లీ కలవొచ్చా?",
  'landing.consult.faq.cancel.a': "క్యాన్సిలేషన్, రీఫండ్ నియమాలు మీరు డబ్బు కట్టే ముందే బుకింగ్ స్క్రీన్‌లో కనిపిస్తాయి. కన్ఫర్మ్ చేసే ముందు అక్కడ చదవండి.",
  'landing.consult.faq.cancel.q': "క్యాన్సిల్ చేయాల్సి వస్తే?",
  'landing.consult.faq.eduId.a': "ఉచిత అకౌంట్ — మీ హెల్త్ రికార్డ్, ఎమర్జెన్సీ కార్డ్, సంక్షోభ సహాయం; వీటికి మేము డబ్బు తీసుకోం. కన్సల్ట్‌కు మాత్రం ప్రతిసారి డబ్బు కట్టాలి. స్లాట్ ఎంచుకునే ముందే డాక్టర్ ఫీజు, ప్లాన్ డిస్కౌంట్ ఏదైనా ఉంటే అది కనిపిస్తాయి. మీరు ఊహించని పేమెంట్ స్క్రీన్ ఎప్పుడూ రాదు.",
  'landing.consult.faq.eduId.q': "నా Edu IDతో నిజంగా ఏమి వస్తుంది?",
  'landing.consult.faq.emergency.a': "Studentkare అనేది ఔట్‌పేషెంట్ టెలికన్సల్టేషన్, క్లినిక్ బుకింగ్ సర్వీస్ — ఎమర్జెన్సీ విభాగం కాదు. ప్రాణాపాయం ఉంటే, ఎరుపు SOS బటన్ నొక్కండి లేదా వెంటనే 112 / Tele-MANAS 14416కి కాల్ చేయండి.",
  'landing.consult.faq.emergency.q': "ఎమర్జెన్సీ అయితే?",
  'landing.consult.faq.private.a': "అవును. Rule L, Studentkare క్యాంపస్ ఫైర్‌వాల్ ప్రకారం, మీరు కన్సల్టేషన్ బుక్ చేసినట్టు మీ సంస్థకు చెప్పం. మెడికల్ నోట్స్, డయాగ్నోసిస్, ప్రిస్క్రిప్షన్లు వారికి కనిపించవు.",
  'landing.consult.faq.private.q': "కన్సల్ట్ విషయం నా కాలేజీకి తెలుస్తుందా?",
  'landing.consult.faq.rx.a': "డాక్టర్ మందులు రాస్తే, ఆ ప్రిస్క్రిప్షన్ డాక్టర్ మాకు ఇచ్చిన రిజిస్ట్రేషన్ నంబర్‌తో మీ వాల్ట్‌లో సేవ్ అవుతుంది. ఆ నంబర్‌ను National Medical Commission రిజిస్టర్‌తో Studentkare ఇంకా సరిచూడటం లేదు. ప్రిస్క్రిప్షన్ ఒప్పుకోవాలా వద్దా అనేది ఫార్మసీ నిర్ణయం.",
  'landing.consult.faq.rx.q': "నాకు వాడుకోగల ప్రిస్క్రిప్షన్ వస్తుందా?",
  'landing.consult.faq.title': "బుక్ చేసే ముందు.",
