  'landing.consult.hero.lede': "మీ Edu IDతో ఉచిత అకౌంట్, మీ హెల్త్ రికార్డ్ వస్తాయి. కన్సల్ట్‌కు మాత్రం డబ్బు కట్టాలి — స్లాట్ ఎంచుకునే ముందే ధర, ప్లాన్ డిస్కౌంట్ ఏదైనా ఉంటే అది కనిపిస్తాయి.",
