  'landing.consult.pillar.listed.body': "డాక్టర్లు, ల్యాబ్‌లు తమంతట తామే లిస్ట్ అవుతారు. రిజిస్ట్రేషన్లు, అక్రెడిటేషన్లను Studentkare ఇంకా తనిఖీ చేయడం లేదు.",
  'landing.consult.pillar.listed.title': "లిస్ట్ అయిన ప్రొవైడర్లు",
  'landing.consult.pillar.near.body': "మీ బ్లాక్ దగ్గరే శాంపిల్ కలెక్షన్, క్లాసుల మధ్య కన్సల్ట్, క్యాంపస్ క్లినిక్ తెరిచి ఉన్నప్పుడు అక్కడ.",
  'landing.consult.pillar.near.title': "మీ హాస్టల్ దగ్గరే",
  'landing.consult.pillar.price.body': "కన్ఫర్మ్ చేసే ముందే ప్రతి ధర స్క్రీన్‌పై ఉంటుంది. ప్లాన్ ధరను మారుస్తుంది, చికిత్సను ఎప్పుడూ కాదు.",
  'landing.consult.pillar.price.title': "బుక్ చేసే ముందే ధర",
  'landing.consult.pillar.private.body': "రికార్డులు మీకూ, మీరు ఎంచుకున్న డాక్టర్‌కూ మాత్రమే తెరుచుకుంటాయి. మీ క్యాంపస్‌కు లెక్కలు మాత్రమే కనిపిస్తాయి, ఫలితాలు ఎప్పుడూ కాదు.",
  'landing.consult.pillar.private.title': "మొదటి నుంచే ప్రైవేట్",
  'landing.consult.pillars.label': "విద్యార్థులు Studentkareని ఎందుకు నమ్ముతారు",
  'landing.consult.promise.price': "బుక్ చేసే ముందే ఫీజు చూపిస్తాం",
  'landing.consult.promise.private': "మీ కాలేజీకి ఎప్పుడూ చెప్పం",
  'landing.consult.promise.rx': "ప్రిస్క్రిప్షన్ మీ వాల్ట్‌లో సేవ్ అవుతుంది",
  'landing.consult.recruit.body': "తీవ్రతను బట్టి వరుసలో ఉన్న క్యూతో క్యాంపస్ క్లినిక్ సెషన్లు తీసుకోండి. విద్యార్థి అనుమతి ఇచ్చినంత వరకే యాక్సెస్, మీ నోట్ నేరుగా విద్యార్థి వాల్ట్‌లోకి వెళ్తుంది.",
  'landing.consult.recruit.cta': "ప్రాక్టీస్‌కు అప్లై చేయండి →",
