  'landing.consult.rule.shared': "మీరు షేర్ చేసిన రికార్డులు, మీరు పెట్టిన రోజుల వరకు",
  'landing.consult.rule.wholeVault': "డాక్టర్ అని మీ వాల్ట్ మొత్తం",
  'landing.consult.rules.eyebrow': "డాక్టర్ ఏమి చూడగలరు",
