  'landing.labtests.empty': "ఇంకా ఏ ల్యాబ్ టెస్టులూ ప్రచురించలేదు.",
  'landing.labtests.eyebrow': "మీ హాస్టల్‌లోనే ల్యాబ్ టెస్టులు",
  'landing.labtests.failed': "ల్యాబ్ టెస్టులు లోడ్ కాలేదు.",
  'landing.labtests.faq1A': "కొన్ని టెస్టులకు మాత్రమే. స్లాట్ ఎంచుకునే ముందే బుకింగ్‌లో చెబుతాం. నీళ్లు ఎప్పుడైనా తాగొచ్చు.",
  'landing.labtests.faq1Q': "ఉపవాసం ఉండాలా?",
  'landing.labtests.faq2A': "మా పార్ట్‌నర్ ల్యాబ్ నుంచి శిక్షణ పొందిన వ్యక్తి మీ హాస్టల్ బ్లాక్ రిసెప్షన్ లేదా లాబీకి వస్తారు. బుకింగ్ ఎక్కడుందో యాప్‌లో చూడొచ్చు: కేటాయించారు, సాంపిల్ తీసుకున్నారు, ల్యాబ్‌లో ఉంది.",
  'landing.labtests.faq2Q': "సాంపిల్ తీసుకోవడానికి ఎవరు వస్తారు?",
  'landing.labtests.faq3A': "హీమోలిసిస్ లేదా సాంపిల్ తక్కువగా ఉండటం మీ తప్పు కాదు. ల్యాబ్ సాంపిల్‌ను టెస్ట్ చేయలేకపోతే, బుకింగ్ మళ్లీ సాంపిల్ దశకు వెళ్తుంది, కొత్తగా సాంపిల్ తీసుకుంటారు.",
  'landing.labtests.faq3Q': "నా సాంపిల్ పనికిరాకపోతే ఏమవుతుంది?",
  'landing.labtests.faq4A': "లేదు. మీ రిపోర్టులు మీ ప్రైవేట్ హెల్త్ వాల్ట్‌లోనే ఉంటాయి. మీ క్యాంపస్‌కు వాటిని చూపించరు.",
  'landing.labtests.faq4Q': "నా కాలేజీ నా రిపోర్టులు చూడగలదా?",
  'landing.labtests.faq5A': "ల్యాబ్ ప్రమాదకరమైన విలువను గుర్తిస్తే, మిగతా రిపోర్ట్ కంటే ముందే వెంటనే మీ వాల్ట్‌లోకి వస్తుంది. మీకు చాలా బాగాలేకపోతే, రిపోర్ట్ కోసం ఆగకండి: 112కి కాల్ చేయండి.",
