  'landing.plans.pillars.label': "మీరు నమ్మగలిగేవి",
  'landing.plans.pillars.listedBody': "డాక్టర్లు, ల్యాబ్‌లు తమను తామే లిస్ట్ చేసుకుంటారు. Studentkare ఇంకా రిజిస్ట్రేషన్‌లను గానీ, అక్రిడిటేషన్‌లను గానీ తనిఖీ చేయడం లేదు.",
