  'landing.subpage.signIn': "సైన్ ఇన్",
  'landing.subpage.trust.label': "విద్యార్థులు Studentkare‌ను ఎందుకు నమ్ముతారు",
  'landing.subpage.trust.listedBody': "డాక్టర్లు, ల్యాబ్‌లు తమను తామే లిస్ట్ చేసుకుంటారు. వారి రిజిస్ట్రేషన్లు, అక్రెడిటేషన్లను Studentkare ఇంకా తనిఖీ చేయడం లేదు.",
  'landing.subpage.trust.listedTitle': "లిస్ట్ అయిన ప్రొవైడర్లు",
  'landing.subpage.trust.nearBody': "మీ బ్లాక్ దగ్గరే శాంపిల్ సేకరణ, క్లాసుల మధ్య కన్సల్ట్, తెరిచి ఉన్నప్పుడు క్యాంపస్ క్లినిక్.",
  'landing.subpage.trust.nearTitle': "మీ హాస్టల్ దగ్గరే",
  'landing.subpage.trust.priceBody': "మీరు కన్ఫర్మ్ చేసే ముందే ప్రతి ధర స్క్రీన్‌పై ఉంటుంది. ప్లాన్ ధరను మారుస్తుంది, వైద్యాన్ని కాదు.",
  'landing.subpage.trust.priceTitle': "బుక్ చేసే ముందే ధర",
  'landing.subpage.trust.privateBody': "రికార్డులు మీకు, మీరు ఎంచుకున్న డాక్టర్‌కు మాత్రమే కనిపిస్తాయి. మీ క్యాంపస్‌కు లెక్కలు మాత్రమే, ఫలితాలు ఎప్పుడూ కాదు.",
  'landing.subpage.trust.privateTitle': "మొదటి నుంచే ప్రైవేట్",
  'landing.subpage.updates.eyebrow': "క్యాంపస్ ఆరోగ్య అప్‌డేట్‌లు",
  'landing.subpage.updates.label': "క్యాంపస్ ఆరోగ్య అప్‌డేట్‌లు",
  'landing.subpage.updates.notYet': "WhatsApp లేదా ఇమెయిల్ ద్వారా అప్‌డేట్‌ల కోసం సైన్-అప్ ఇంకా ప్రారంభం కాలేదు. ప్రారంభమైనప్పుడు ఇక్కడే చేరవచ్చు.",
  'landing.subpage.updates.title': "క్యాంప్ తేదీలు, సీజన్ హెచ్చరికలు, సులభమైన భాషలో ఆరోగ్య సూచనలు.",
  'landing.wellness.badgeNoTimetable': "ఇంకా టైమ్‌టేబుల్ ప్రచురించలేదు",
