  'landing.wellness.cat.yoga.label': "యోగా",
  'landing.wellness.eyebrow': "వెల్‌నెస్ & ట్రైనింగ్",
  'landing.wellness.footerNote': "మీ క్యాంపస్ టైమ్‌టేబుల్ ప్రచురించిన తర్వాత సెషన్‌లు ఇక్కడ కనిపిస్తాయి.",
  'landing.wellness.judgmentCardBody': "ఎవరూ స్ట్రీక్ చూడరు, హాజరు గురించి మాట్లాడరు. పరీక్షల వల్ల మూడు వారాలు రాకపోయినా ఏమీ తగ్గించరు, జరిమానా లేదు. కదలిక మీ ఆరోగ్యం కోసం, ఏ అల్గారిథమ్ కోసమో కాదు.",
  'landing.wellness.judgmentCardTitle': "కొత్తవారికి, చదువు షెడ్యూల్‌కు తగ్గట్టు",
  'landing.wellness.judgmentTitle': "తీర్పు లేని కదలిక",
  'landing.wellness.kindsEyebrow': "ఏమి ప్లాన్ చేశాం",
  'landing.wellness.kindsNote': "మీ క్యాంపస్ టైమ్‌టేబుల్ ప్రచురించినప్పుడు ధరలు, సమయాలు, ప్రదేశాలు నిర్ణయమవుతాయి.",
  'landing.wellness.kindsTitle': "ఆరు రకాల సెషన్‌లు",
  'landing.wellness.lede': "క్యాంపస్‌లో జిమ్, స్ట్రెంత్, యోగా, ధ్యానం సెషన్‌లు — మీ క్యాంపస్ వాటిని ప్రారంభించినప్పుడు. లీడర్‌బోర్డులు లేవు, శరీర స్కోర్లు లేవు.",
  'landing.wellness.mindBody': "గైడెడ్ ధ్యానం, శ్వాస వ్యాయామాలు, యోగ నిద్ర — మీ క్యాంపస్ వాటిని షెడ్యూల్ చేసినప్పుడు.",
  'landing.wellness.mindEyebrow': "మనసు",
  'landing.wellness.mindTitle': "కండరాన్ని తర్ఫీదు చేసినట్టే మీ ఏకాగ్రతనూ తర్ఫీదు చేయండి.",
  'landing.wellness.notOpenYet': "ఇంకా ప్రారంభం కాలేదు",
  'landing.wellness.safety.hurt.body': "సెషన్ మధ్యలో నొప్పి వస్తే సెషన్ ఆపేస్తారు, కోచ్ మిమ్మల్ని డాక్టర్ దగ్గరకు పంపుతారు.",
  'landing.wellness.safety.hurt.title': "నొప్పిగా ఉందా? ఆపి చూపించుకోండి",
  'landing.wellness.safety.noBoards.body': "హాజరు మీకు మాత్రమే తెలుస్తుంది. ఎవరు వచ్చారో, ఎవరు రాలేదో, మీరు ఎంత ఎత్తారో ఎవరూ చూడరు.",
  'landing.wellness.safety.noBoards.title': "లీడర్‌బోర్డులు లేవు",
  'landing.wellness.safety.noWeight.body': "ఇక్కడ శరీర బరువు, కేలరీలు, శరీర ఆకృతిని ట్రాక్ చేయం. రావడం, మంచిగా అనిపించడమే ప్రగతి.",
  'landing.wellness.safety.noWeight.title': "బరువు లేదు, కేలరీలు లేవు",
  'landing.wellness.safety.readiness.body': "మొదటి సెషన్‌కు ముందు చిన్న ఆరోగ్య ప్రశ్నావళి. అందులో ఏదైనా తేలితే అది డాక్టర్‌కు వెళ్తుంది, కోచ్‌కు కాదు.",
  'landing.wellness.safety.readiness.title': "ముందు సిద్ధత తనిఖీ",
  'landing.wellness.safetyEyebrow': "సురక్షితంగా ఎలా ఉంచుతాం",
  'landing.wellness.safetyTitle': "సెషన్‌లు ఎలా నడవాలి",
  'landing.wellness.seeTimetable': "టైమ్‌టేబుల్ చూడండి",
  'landing.wellness.talkNow': "ఇప్పుడే ఎవరితోనైనా మాట్లాడాలా?",
  'landing.wellness.timetableEmpty': "ఇంకా ఏ సెషన్‌లూ షెడ్యూల్ కాలేదు. మీ క్యాంపస్ టైమ్‌టేబుల్ ప్రచురించినప్పుడు ఇక్కడ కనిపిస్తుంది.",
  'landing.wellness.timetableTitle': "టైమ్‌టేబుల్",
  'landing.wellness.title': "క్లాసుల మధ్య — కదలండి, స్ట్రెచ్ చేయండి, శ్వాస తీసుకోండి.",
  'landing.wellness.track.sleep.body': "రాత్రి పది నిమిషాల గైడెడ్ సెషన్‌లు. అలవాటు ఏర్పడుతుంది, స్కోర్ కాదు.",
  'landing.wellness.track.sleep.name': "నిద్ర & శ్వాస",
  'landing.wellness.track.strength.body': "వారానికి రెండు సెషన్‌లు. కోచ్ మీ పద్ధతి గమనిస్తుండగా ఐదు కదలికలు నేర్చుకోండి.",
  'landing.wellness.track.strength.name': "స్ట్రెంత్ బేసిక్స్",
  'landing.wellness.track.walk.body': "నడక-పరుగు మార్చి మార్చి. ఏ వేగమైనా సరే, ఎవరికీ టైమ్ చూడరు.",
