  'landing.partners.firewall.intro': "आवेदन से पहले इसे पढ़ें। अगर आपके मॉडल को टार्गेटिंग या प्लेसमेंट चाहिए, तो हम सही प्लेटफ़ॉर्म नहीं हैं, और यह हम कॉन्ट्रैक्ट के बाद नहीं, अभी बताना चाहेंगे।",
  'landing.partners.firewall.title': "यहाँ आप क्या नहीं ख़रीद सकते",
  'landing.partners.footer.note': "Studentkare अभी बन रहा है, और यह पेज जानबूझकर बताता है कि क्या कमी है। जब तक कोई पार्टनर साइन करके लिखित में दिखने की सहमति नहीं देता, हम उसका लोगो नहीं दिखाते।",
  'landing.partners.footer.privacy': "प्राइवेसी",
  'landing.partners.footer.terms': "शर्तें",
  'landing.partners.gap.body': "हमारे डिज़ाइन कहते हैं कि रेट हर लाइन पर दिखेगा। सिस्टम में अभी कोई रेट तय नहीं है, इसलिए यहाँ ईमानदारी से दिखाने को कुछ नहीं है। रेट तय होने पर ही यह इस पेज और हर स्टेटमेंट लाइन पर दिखेगा — उससे पहले नहीं।",
  'landing.partners.gap.title': "कमीशन अभी प्रकाशित नहीं है।",
  'landing.partners.lede': "यहाँ कोई स्पॉन्सर्ड स्लॉट नहीं हैं, क्योंकि आपको बेचने के लिए कुछ है ही नहीं। प्रोवाइडर सर्च पहले यह देखता है कि आप छात्र के पिनकोड पर सेवा देते हैं या नहीं, फिर वर्णमाला क्रम — कभी इस पर नहीं कि आप कितना देते हैं। दिखने का तरीका है कैंपस की अच्छी सेवा करना।",
  'landing.partners.nfs.ads': "विज्ञापन स्लॉट। ऐसे कोई स्लॉट नहीं हैं, और किसी भी चीज़ के लिए पैसे देने से किसी सदस्य का रिकॉर्ड देखने का हक़ नहीं मिलता।",
  'landing.partners.nfs.record': "छात्र के हेल्थ रिकॉर्ड की कोई भी चीज़ — टार्गेटिंग, सेगमेंटेशन या किसी और काम के लिए। क्लिनिकल डेटा व्यावसायिक हिस्सों तक नहीं पहुँचता।",
  'landing.partners.nfs.search': "सर्च नतीजों में जगह। क्रम पहले पिनकोड मिलान, फिर नाम है, और API हर जवाब में यही बताता है।",
