  'landing.plans.empty': "अभी कोई प्लान उपलब्ध नहीं है।",
  'landing.plans.faq.a1': "आपने जो भी सहेजा है, वह आपके रिकॉर्ड में रहता है — पढ़ने और एक्सपोर्ट करने लायक। प्लान बंद करने से सिर्फ़ उसके अतिरिक्त फ़ायदे बंद होते हैं — पहले से सहेजा कुछ भी न मिटता है, न लॉक होता है।",
  'landing.plans.faq.a2': "नहीं। मेडिकल प्राथमिकता सिर्फ़ ज़रूरत की गंभीरता से तय होती है। प्लान अतिरिक्त फ़ायदों के लिए है, मेडिकल कतार में आगे जगह के लिए कभी नहीं।",
  'landing.plans.faq.a3': "नहीं। Studentkare प्लान अतिरिक्त फ़ायदों वाली मेंबरशिप हैं। ये स्वास्थ्य बीमा नहीं हैं और इमरजेंसी मेडिकल कवर की जगह नहीं लेते।",
  'landing.plans.faq.a4': "हाँ, अगर आपका कैंपस संस्थागत प्लान लेता है। संस्था के भुगतान करने पर भी आपके रिकॉर्ड निजी रहते हैं — कॉलेज उन्हें नहीं खोल सकता।",
