  'landing.plans.h1': "प्लान से आपकी कीमत बदलती है। आपके इलाज का तरीका कभी नहीं बदलता।",
  'landing.plans.homeLink': "Studentkare होम",
  'landing.plans.intro': "हर छात्र का अकाउंट मुफ़्त है: आपके रिकॉर्ड, इमरजेंसी कॉन्टैक्ट और संकट में मदद — इनका कोई पैसा नहीं लगता। पेड प्लान कुछ अतिरिक्त फ़ायदे देते हैं, जो नीचे हर प्लान में लिखे हैं।",
  'landing.plans.loadFailedBody': "हम कीमतें सिर्फ़ अपनी मौजूदा प्लान सूची से दिखाते हैं, इसलिए यहाँ कोई कीमत नहीं दिखाई गई है। थोड़ी देर में फिर कोशिश करें।",
  'landing.plans.loadFailedTitle': "प्लान लोड नहीं हो सके।",
  'landing.plans.loading': "प्लान लोड हो रहे हैं…",
  'landing.plans.money.body': "अभी कोई कमीशन दर तय नहीं है, इसलिए दिखाने को कोई बँटवारा नहीं है। जब तय होगी, यहीं साफ़-साफ़ लिखी जाएगी, छिपाई नहीं जाएगी। लिस्टिंग हर हाल में मुफ़्त है — दिखने के लिए कोई पैसे नहीं देता।",
  'landing.plans.money.eyebrow': "आपका पैसा कहाँ जाता है",
  'landing.plans.money.ranking': "छात्र को क्या दिखे, यह कमीशन कभी नहीं बदलता। लिस्टिंग पहले पिनकोड मिलान से, फिर नाम से क्रम में होती है — कमीशन या पैसे देकर मिली जगह से कभी नहीं।",
  'landing.plans.money.title': "कमीशन लेने से पहले हम उसे सबके सामने बताएँगे।",
  'landing.plans.native.createFree': "मुफ़्त अकाउंट बनाएँ",
  'landing.plans.native.exploreConsults': "कंसल्टेशन देखें",
  'landing.plans.native.firewallBody': "लैब रिपोर्ट, रीडिंग और पर्चे भुगतान की जानकारी से अलग रखे जाते हैं। कोई विज्ञापन नहीं है, और प्लान के पैसे देने वाले कैंपस को आपके रिकॉर्ड तक कोई पहुँच नहीं मिलती।",
  'landing.plans.native.firewallTitle': "मेडिकल जानकारी कारोबार से अलग रखी जाती है",
  'landing.plans.native.footerNote': "रद्द करने या पैसे देना बंद करने पर भी सहेजे रिकॉर्ड आपके ही रहते हैं।",
  'landing.plans.native.meta': "कीमतें रुपये में हैं। अपने रिकॉर्ड एक्सपोर्ट करना हमेशा मुफ़्त है।",
  'landing.plans.native.plansBody': "हर छात्र का अकाउंट मुफ़्त है। पेड प्लान और उनकी मौजूदा कीमतें studentkare.co/plans पर हैं। यह ऐप उन्हें अभी नहीं दिखाता, इसलिए यहाँ कोई कीमत नहीं बताई गई है।",
