  'landing.programs.cta': "शुरू करने के लिए कंसल्ट बुक करें →",
  'landing.programs.ctaNote': "कंसल्ट के बाद डॉक्टर आपको जोड़ते हैं। जुड़ना मुफ़्त है; प्रोग्राम के कंसल्ट और टेस्ट का भुगतान हर बार इस्तेमाल पर। जब चाहें छोड़ें — आपके रिकॉर्ड आपके ही रहते हैं।",
  'landing.programs.eyebrow': "केयर प्रोग्राम",
  'landing.programs.faq1A': "नहीं, और लेना भी नहीं चाहिए। प्रोग्राम पढ़ाई के दिनों में चीज़ें संभाले रखता है — रीफ़िल, रिपीट टेस्ट, बात करने को कोई। आपके डॉक्टर आपके डॉक्टर ही रहते हैं, और यहाँ दर्ज जानकारी आप उनसे शेयर कर सकते हैं।",
  'landing.programs.faq1Q': "घर पर मेरे डॉक्टर पहले से हैं। क्या यह उनकी जगह लेगा?",
  'landing.programs.faq2A': "जुड़ना मुफ़्त है। प्रोग्राम के कंसल्ट, रीफ़िल और लैब टेस्ट का भुगतान हर बार इस्तेमाल पर, और कन्फ़र्म करने से पहले कीमत दिखती है। कोई लॉक-इन फ़ीस नहीं, छूटी अपॉइंटमेंट पर कोई जुर्माना नहीं।",
  'landing.programs.faq2Q': "इसका खर्च कितना है?",
  'landing.programs.faq3A': "हाँ। छुट्टियों में भी टेली-कंसल्ट चलते रहते हैं, और जहाँ आपके पास कोई पार्टनर लैब लिस्टेड हो वहाँ लैब टेस्ट बुक कर सकते हैं।",
  'landing.programs.faq3Q': "क्या छुट्टियों में भी जुड़ा रह सकता/सकती हूँ?",
  'landing.programs.faq4A': "जिस दिन आप छोड़ते हैं, सहमति उसी दिन खत्म। आपके रिकॉर्ड आपके ही रहते हैं, आपके वॉल्ट में, और आप उन्हें एक्सपोर्ट कर सकते हैं।",
  'landing.programs.faq4Q': "छोड़ने पर मेरे रिकॉर्ड का क्या होगा?",
  'landing.programs.faq5A': "अगर आप 18 या उससे ज़्यादा उम्र के हैं, तो नहीं। जब तक आप खुद शेयर न करें, आपके रिकॉर्ड, डायग्नोसिस और प्रिस्क्रिप्शन आपके कैंपस या माता-पिता को नहीं दिखते।",
  'landing.programs.faq5Q': "क्या मेरे माता-पिता को बताया जाएगा?",
  'landing.programs.faqTitle': "जुड़ने से पहले।",
  'landing.programs.footerNote': "केयर प्रोग्राम घर के आपके स्पेशलिस्ट की जगह नहीं लेते। आपके रिकॉर्ड आपके हैं और आप उन्हें एक्सपोर्ट कर सकते हैं।",
  'landing.programs.include1Body': "जो खाली हो वह नहीं। वे आपकी हिस्ट्री देखते हैं, बार-बार समझाना नहीं पड़ता।",
  'landing.programs.include1Title': "पूरी कहानी जानने वाले एक ही डॉक्टर",
  'landing.programs.include2Body': "कब दी गई और कितने दिन चलेगी, उसी से हिसाब — रिमाइंडर लगाने की ज़रूरत नहीं।",
  'landing.programs.include2Title': "आपके कोर्स के हिसाब से रीफ़िल",
